);

create temporary table seed_police_math_set_04 (
  position integer primary key,
  data jsonb not null
) on commit drop;

insert into seed_police_math_set_04 (position, data)
select ordinality::integer, value
from jsonb_array_elements($questions$
[
  {"category":"อนุกรม","prompt":"4, 9, 19, 39, 79, ... จำนวนถัดไปคือข้อใด","answer":"159","choices":["149","151","159","161"],"explanation":"สังเกตความสัมพันธ์ของพจน์ที่อยู่ติดกันก่อน จะเห็นว่า 4 → 9 คือ 4 × 2 + 1, 9 → 19 คือ 9 × 2 + 1, 19 → 39 คือ 19 × 2 + 1 และ 39 → 79 คือ 39 × 2 + 1 ดังนั้นกฎของอนุกรมนี้คือ ‘นำพจน์เดิมคูณ 2 แล้วบวก 1’ เมื่อต้องหาพจน์ถัดจาก 79 จึงได้ 79 × 2 + 1 = 158 + 1 = 159 อีกวิธีหนึ่งคือดูผลต่าง 5, 10, 20, 40 ซึ่งเพิ่มเป็น 2 เท่าทุกครั้ง ผลต่างถัดไปจึงเป็น 80 และ 79 + 80 = 159 เช่นกัน ดังนั้นคำตอบคือ 159","tip":"จำสั้น ๆ: ถ้าผลต่างเพิ่มเป็น 2 เท่าต่อเนื่อง ให้ลองมองกฎแบบ “พจน์เดิม × 2 ± ค่าคงที่” ก่อน"},
  {"category":"อนุกรม","prompt":"2, 6, 12, 20, 30, ... จำนวนถัดไปคือข้อใด","answer":"42","choices":["38","40","42","44"],"explanation":"เริ่มจากหาผลต่างของพจน์ที่ติดกัน: 6 - 2 = 4, 12 - 6 = 6, 20 - 12 = 8 และ 30 - 20 = 10 จะเห็นว่าผลต่างเป็น 4, 6, 8, 10 ซึ่งเพิ่มขึ้นครั้งละ 2 ดังนั้นผลต่างถัดไปต้องเป็น 12 เมื่อนำไปบวกกับพจน์ล่าสุด 30 จะได้ 30 + 12 = 42 จึงสรุปว่าจำนวนถัดไปคือ 42 จุดสำคัญของโจทย์ลักษณะนี้คืออย่าดูเฉพาะตัวเลขเดิม แต่ให้สร้างชุด ‘ผลต่าง’ ขึ้นมาแล้วหารูปแบบของผลต่างอีกชั้นหนึ่ง","tip":"จำสั้น ๆ: อนุกรมที่ตัวเลขเพิ่มไม่คงที่ ให้สร้างแถว “ผลต่าง” ใต้โจทย์ก่อน แล้วดูว่าผลต่างมีรูปแบบอะไร"},
  {"category":"อนุกรม","prompt":"4, 7, 13, 25, 49, ... จำนวนถัดไปคือข้อใด","answer":"97","choices":["95","97","99","101"],"explanation":"ตรวจพจน์ทีละคู่จะพบว่า 4 → 7 คือ 4 × 2 - 1, 7 → 13 คือ 7 × 2 - 1, 13 → 25 คือ 13 × 2 - 1 และ 25 → 49 คือ 25 × 2 - 1 จึงได้กฎว่า ‘พจน์ถัดไป = พจน์ก่อนหน้า × 2 - 1’ ดังนั้นพจน์ที่ถัดจาก 49 คือ 49 × 2 - 1 = 98 - 1 = 97 สามารถตรวจสอบอีกทางจากผลต่าง 3, 6, 12, 24 ซึ่งเพิ่มเป็น 2 เท่าทุกครั้ง ผลต่างถัดไปคือ 48 และ 49 + 48 = 97 จึงตอบ 97","tip":"จำสั้น ๆ: ถ้าผลต่างเป็น 3, 6, 12, 24,... ให้คิดทันทีว่าพจน์ถัดไปอาจมาจาก “×2 แล้วบวก/ลบค่าคงที่”"},
  {"category":"อุปมาอุปไมย","prompt":"หนังสือ : อ่าน เปรียบได้กับ อาหาร : ?","answer":"รับประทาน","choices":["ปรุง","รับประทาน","ซื้อ","ขาย"],"explanation":"โจทย์เป็นอุปมาอุปไมยแบบ ‘สิ่งของ : หน้าที่หลักของสิ่งนั้น’ หนังสือมีหน้าที่หลักคือใช้สำหรับอ่าน ดังนั้นเมื่อเปลี่ยนเป็น ‘อาหาร : ?’ คำที่มีความสัมพันธ์แบบเดียวกันควรเป็นการกระทำหลักที่ทำกับอาหาร คือ ‘รับประทาน’ ตัวเลือก ‘ปรุง’ เป็นเพียงขั้นตอนก่อนรับประทาน ไม่ใช่หน้าที่หลักของอาหาร ส่วน ‘ซื้อ’ และ ‘ขาย’ เป็นกิจกรรมทางการค้า ไม่ใช่ความสัมพันธ์โดยตรงแบบเดียวกับ หนังสือ : อ่าน ดังนั้นคำตอบคือ รับประทาน","tip":"จำสั้น ๆ: อุปมาอุปไมยให้หาความสัมพันธ์เป็นคำกริยา เช่น “สิ่งของ → ใช้ทำอะไร” แล้วใช้ความสัมพันธ์เดิมกับคำคู่ถัดไป"},
  {"category":"ลำดับเหตุการณ์","prompt":"ถ้า ก เสร็จงานหลัง ข แต่ก่อน ค และ ง เสร็จก่อน ข ใครเสร็จงานเป็นคนแรก","answer":"ง","choices":["ก","ข","ค","ง"],"explanation":"แปลงเงื่อนไขแต่ละประโยคให้อยู่ในรูปของลำดับก่อน คำว่า ‘ก เสร็จงานหลัง ข’ หมายถึง ข มาก่อน ก และ ‘ก ก่อน ค’ หมายถึง ก มาก่อน ค ดังนั้นจากสองเงื่อนไขแรกได้ ข → ก → ค ต่อมา ‘ง เสร็จก่อน ข’ จึงต้องนำ ง ไปไว้ก่อน ข เมื่อนำทุกเงื่อนไขมารวมกันจะได้ลำดับ ง → ข → ก → ค ดังนั้นผู้ที่เสร็จงานเป็นคนแรกคือ ง การทำโจทย์แบบนี้ควรเขียนลูกศรหรือลำดับทุกครั้งเพื่อลดความสับสนจากคำว่า ก่อน และ หลัง","tip":"จำสั้น ๆ: แปลงทุกประโยคเป็นลูกศร ก่อน → หลัง แล้วค่อยต่อเป็นเส้นเดียว จะลดการสลับคำว่า “ก่อน/หลัง”"},
  {"category":"อัตราส่วน","prompt":"แบ่งเงิน 640 บาท เป็นอัตราส่วน 3 : 5 ส่วนที่มากกว่ามีเงินกี่บาท","answer":"400 บาท","choices":["240 บาท","320 บาท","400 บาท","480 บาท"],"explanation":"อัตราส่วน 3 : 5 หมายถึงเงินทั้งหมดถูกแบ่งเป็น 3 + 5 = 8 ส่วนเท่า ๆ กัน เงินรวมมี 640 บาท ดังนั้นเงินต่อ 1 ส่วนเท่ากับ 640 ÷ 8 = 80 บาท ส่วนที่มากกว่าคือฝั่ง 5 ส่วน จึงมีเงิน 5 × 80 = 400 บาท ส่วนอีกฝั่ง 3 ส่วนจะมี 3 × 80 = 240 บาท และตรวจสอบได้ว่า 240 + 400 = 640 บาทตรงกับเงินทั้งหมด ดังนั้นส่วนที่มากกว่ามีเงิน 400 บาท","tip":"จำสั้น ๆ: อัตราส่วน 3:5 ให้ทำ 3 ขั้น — รวมส่วน 8 → หาค่า 1 ส่วน → คูณกลับตามจำนวนส่วนที่ถาม"},
  {"category":"ร้อยละ","prompt":"สินค้าราคา 800 บาท ขึ้นราคา 15% แล้วลดราคา 15% ราคาสุดท้ายเท่าใด","answer":"782 บาท","choices":["780 บาท","782 บาท","800 บาท","818 บาท"],"explanation":"การขึ้นราคา 15% ต้องคิดจากราคาเดิม 800 บาท จึงได้ราคาใหม่ 800 × 1.15 = 920 บาท จากนั้นการลดราคา 15% ต้องคิดจาก ‘ราคาใหม่ 920 บาท’ ไม่ใช่คิดจาก 800 บาท จำนวนเงินที่ลดคือ 920 × 0.15 = 138 บาท ดังนั้นราคาสุดท้าย = 920 - 138 = 782 บาท หรือคำนวณรวดเดียวเป็น 800 × 1.15 × 0.85 = 782 บาท เหตุผลที่ราคาไม่กลับมาเป็น 800 บาท เพราะเปอร์เซ็นต์ตอนขึ้นและตอนลดใช้ฐานคนละจำนวนกัน","tip":"จำสั้น ๆ: เปอร์เซ็นต์หลายขั้นให้คูณตัวคูณต่อกัน เช่น +15% = ×1.15 และ −15% = ×0.85 ห้ามหักล้างกันตรง ๆ"},
  {"category":"ค่าเฉลี่ย","prompt":"นักเรียน 12 คนมีคะแนนเฉลี่ย 18 คะแนน ถ้าเพิ่มนักเรียนอีก 3 คนที่ได้คนละ 26 คะแนน คะแนนเฉลี่ยใหม่เท่าใด","answer":"19.6 คะแนน","choices":["19 คะแนน","19.6 คะแนน","20 คะแนน","20.4 คะแนน"],"explanation":"คะแนนเฉลี่ยเดิม 18 คะแนนของนักเรียน 12 คน หมายความว่าคะแนนรวมเดิมเท่ากับ 12 × 18 = 216 คะแนน นักเรียนใหม่ 3 คนได้คนละ 26 คะแนน จึงเพิ่มคะแนนรวม 3 × 26 = 78 คะแนน คะแนนรวมใหม่เป็น 216 + 78 = 294 คะแนน และจำนวนนักเรียนใหม่ทั้งหมดเป็น 12 + 3 = 15 คน ดังนั้นค่าเฉลี่ยใหม่ = 294 ÷ 15 = 19.6 คะแนน การหาค่าเฉลี่ยเมื่อมีสมาชิกเพิ่มต้องกลับไปหาผลรวมก่อน แล้วจึงหารด้วยจำนวนสมาชิกใหม่ทั้งหมด","tip":"จำสั้น ๆ: ค่าเฉลี่ยเปลี่ยนเมื่อมีคนเพิ่ม ให้ย้อนกลับเป็น “ผลรวมเดิม” ก่อนเสมอ แล้วจึงบวกข้อมูลใหม่และหารจำนวนคนใหม่"},
  {"category":"สมการ","prompt":"สามเท่าของจำนวนหนึ่งบวก 7 เท่ากับ 34 จำนวนนั้นเท่าใด","answer":"9","choices":["7","8","9","10"],"explanation":"ให้จำนวนที่ต้องการหาเป็น x จากข้อความ ‘สามเท่าของจำนวนหนึ่งบวก 7 เท่ากับ 34’ เขียนเป็นสมการได้ว่า 3x + 7 = 34 ขั้นแรกย้าย 7 ไปอีกข้างโดยลบ 7 ทั้งสองข้าง จะได้ 3x = 34 - 7 = 27 จากนั้นหารทั้งสองข้างด้วย 3 จึงได้ x = 27 ÷ 3 = 9 ตรวจคำตอบโดยแทนค่า 9 กลับเข้าโจทย์: 3(9) + 7 = 27 + 7 = 34 ถูกต้อง ดังนั้นจำนวนนั้นคือ 9","tip":"จำสั้น ๆ: แก้สมการเชิงเส้นให้ “แยก x ให้อยู่ข้างเดียว” — ย้ายค่าคงที่ก่อน แล้วค่อยหารสัมประสิทธิ์"},
  {"category":"อายุ","prompt":"ปัจจุบันพ่ออายุเป็น 4 เท่าของบุตร อีก 12 ปีข้างหน้าพ่อจะอายุเป็น 2 เท่าของบุตร ปัจจุบันบุตรอายุกี่ปี","answer":"6 ปี","choices":["4 ปี","5 ปี","6 ปี","8 ปี"],"explanation":"ให้บุตรมีอายุปัจจุบัน x ปี ดังนั้นพ่อมีอายุปัจจุบัน 4x ปี อีก 12 ปี บุตรจะอายุ x + 12 ปี และพ่อจะอายุ 4x + 12 ปี ตามโจทย์ ในเวลานั้นพ่อมีอายุเป็น 2 เท่าของบุตร จึงตั้งสมการได้ว่า 4x + 12 = 2(x + 12) กระจายวงเล็บเป็น 4x + 12 = 2x + 24 ย้าย 2x มาด้านซ้ายและย้าย 12 ไปด้านขวา จะได้ 2x = 12 ดังนั้น x = 6 จึงสรุปว่าปัจจุบันบุตรอายุ 6 ปี ตรวจคำตอบ: พ่ออายุ 24 ปี อีก 12 ปีพ่ออายุ 36 ปี และบุตรอายุ 18 ปี ซึ่ง 36 = 2 × 18 พอดี","tip":"จำสั้น ๆ: โจทย์อายุให้ตั้งอายุ “ปัจจุบัน” เป็นตัวแปรก่อน แล้วเพิ่มจำนวนปีเดียวกันให้ทุกคนในอนาคต"},
  {"category":"งานและเวลา","prompt":"ก ทำงานชิ้นหนึ่งเสร็จใน 6 วัน ข ทำงานเดียวกันเสร็จใน 3 วัน หากทำร่วมกันจะเสร็จในกี่วัน","answer":"2 วัน","choices":["1.5 วัน","2 วัน","2.5 วัน","3 วัน"],"explanation":"อย่านำจำนวนวัน 6 และ 3 มาบวกกันโดยตรง เพราะต้องเปลี่ยนเป็น ‘อัตราการทำงานต่อวัน’ ก่อน ก ทำงานเสร็จใน 6 วัน แปลว่า 1 วันทำได้ 1/6 ของงาน ส่วน ข ทำเสร็จใน 3 วัน แปลว่า 1 วันทำได้ 1/3 ของงาน เมื่อทำร่วมกัน อัตรารวมต่อวัน = 1/6 + 1/3 = 1/6 + 2/6 = 3/6 = 1/2 งานต่อวัน ถ้าทำได้วันละ 1/2 งาน งานทั้งหมด 1 งานจะใช้เวลา 1 ÷ (1/2) = 2 วัน ดังนั้นทำร่วมกันเสร็จใน 2 วัน","tip":"จำสั้น ๆ: งานและเวลาอย่าบวก “จำนวนวัน” ให้เปลี่ยนเป็น “งานต่อวัน” แล้วบวกอัตราการทำงานแทน"},
  {"category":"ความน่าจะเป็น","prompt":"กล่องหนึ่งมีลูกบอลแดง 3 ลูก น้ำเงิน 2 ลูก หยิบพร้อมกัน 2 ลูก ความน่าจะเป็นที่จะได้สีแดงทั้งสองลูกเท่าใด","answer":"3/10","choices":["1/5","3/10","2/5","1/2"],"explanation":"ลูกบอลทั้งหมดมี 3 + 2 = 5 ลูก ต้องหยิบพร้อมกัน 2 ลูก จำนวนวิธีเลือก 2 ลูกจากทั้งหมด 5 ลูกคือ C(5,2) = 10 วิธี ส่วนกรณีที่ต้องการคือได้ลูกบอลสีแดงทั้ง 2 ลูก ซึ่งมีลูกบอลแดง 3 ลูก จำนวนวิธีเลือกแดง 2 ลูกจาก 3 ลูกคือ C(3,2) = 3 วิธี ดังนั้นความน่าจะเป็น = จำนวนกรณีที่ต้องการ ÷ จำนวนกรณีทั้งหมด = 3/10 สามารถตรวจอีกวิธีโดยคิดแบบหยิบทีละลูกโดยไม่คืน: (3/5) × (2/4) = 6/20 = 3/10 ได้คำตอบเดียวกัน","tip":"จำสั้น ๆ: หยิบพร้อมกันและไม่สนใจลำดับ ใช้การจัดหมู่ C(n,r); ถ้าหยิบทีละลูก ให้คูณความน่าจะเป็นแบบไม่คืน"},
  {"category":"ความน่าจะเป็น","prompt":"ทอดลูกเต๋า 1 ลูก 2 ครั้ง ความน่าจะเป็นที่ผลรวมเป็น 7 เท่ากับเท่าใด","answer":"1/6","choices":["1/9","1/6","5/18","7/36"],"explanation":"ทอดลูกเต๋า 1 ลูก 2 ครั้ง แต่ละครั้งมีผลลัพธ์ 6 แบบ ดังนั้นผลลัพธ์ที่เป็นไปได้ทั้งหมดมี 6 × 6 = 36 แบบ ผลรวมเป็น 7 เกิดได้จากคู่ลำดับ (1,6), (2,5), (3,4), (4,3), (5,2), (6,1) รวม 6 แบบ ดังนั้นความน่าจะเป็น = 6/36 = 1/6 จุดที่ต้องระวังคือการทอดครั้งที่ 1 และครั้งที่ 2 ถือเป็นคนละตำแหน่ง เช่น (1,6) และ (6,1) จึงนับเป็นคนละผลลัพธ์","tip":"จำสั้น ๆ: ลูกเต๋า 2 ครั้งมี 6×6 = 36 ผลลัพธ์เสมอ จากนั้นนับคู่ลำดับที่ตรงเงื่อนไข"},
  {"category":"การนับจำนวน","prompt":"มีเสื้อ 4 ตัว กางเกง 3 ตัว เลือกแต่งตัวโดยเลือกอย่างละ 1 ชิ้น ทำได้กี่แบบ","answer":"12 แบบ","choices":["7 แบบ","12 แบบ","16 แบบ","24 แบบ"],"explanation":"การแต่งตัวหนึ่งชุดต้องเลือกเสื้อ 1 ตัวและกางเกง 1 ตัว สำหรับเสื้อแต่ละตัวมีทางเลือกกางเกงได้ 3 ตัว หากมีเสื้อ 4 ตัว จึงมีจำนวนชุดทั้งหมด = 4 × 3 = 12 แบบ นี่คือหลักการคูณ: เมื่อการตัดสินใจประกอบด้วยหลายขั้นตอนต่อเนื่องกัน และแต่ละขั้นเป็นอิสระต่อกัน ให้นำจำนวนทางเลือกของแต่ละขั้นมาคูณกัน ดังนั้นทำได้ทั้งหมด 12 แบบ","tip":"จำสั้น ๆ: เลือกของหลายขั้นที่ต้องทำทุกขั้น ให้ใช้ “หลักการคูณ” จำนวนทางเลือกของแต่ละขั้นเข้าด้วยกัน"},
  {"category":"การจัดเรียง","prompt":"จำนวนวิธีเรียงหนังสือแตกต่างกัน 5 เล่มบนชั้นเป็นแถวตรงมีกี่วิธี","answer":"120 วิธี","choices":["24 วิธี","60 วิธี","120 วิธี","240 วิธี"],"explanation":"หนังสือทั้ง 5 เล่มแตกต่างกันและต้องเรียงเป็นแถวตรง ตำแหน่งแรกเลือกได้ 5 วิธี เมื่อตำแหน่งแรกถูกใช้ไปแล้ว ตำแหน่งที่สองเหลือ 4 วิธี ตำแหน่งที่สามเหลือ 3 วิธี ตำแหน่งที่สี่เหลือ 2 วิธี และตำแหน่งสุดท้ายเหลือ 1 วิธี ดังนั้นจำนวนวิธีทั้งหมด = 5 × 4 × 3 × 2 × 1 = 5! = 120 วิธี จึงตอบ 120 วิธี โจทย์เรียงสิ่งของที่แตกต่างกันทั้งหมด n ชิ้นเป็นแถวตรงใช้สูตร n!","tip":"จำสั้น ๆ: ของ n ชิ้น “แตกต่างกันทั้งหมด” และเรียงเป็นแถวตรง → ใช้ n! ทันที"},
  {"category":"อัตราเร็ว","prompt":"รถยนต์วิ่งด้วยความเร็วคงที่ 60 กิโลเมตรต่อชั่วโมง เป็นระยะทาง 180 กิโลเมตร ใช้เวลากี่ชั่วโมง","answer":"3 ชั่วโมง","choices":["2 ชั่วโมง","2.5 ชั่วโมง","3 ชั่วโมง","3.5 ชั่วโมง"],"explanation":"ใช้ความสัมพันธ์ ระยะทาง = ความเร็ว × เวลา เมื่อต้องการหาเวลาให้จัดรูปเป็น เวลา = ระยะทาง ÷ ความเร็ว รถเดินทาง 180 กิโลเมตรด้วยความเร็วคงที่ 60 กิโลเมตรต่อชั่วโมง จึงใช้เวลา = 180 ÷ 60 = 3 ชั่วโมง ตรวจสอบโดย 60 × 3 = 180 กิโลเมตรตรงกับระยะทางในโจทย์ ดังนั้นคำตอบคือ 3 ชั่วโมง","tip":"จำสั้น ๆ: สามเหลี่ยม ระยะทาง–ความเร็ว–เวลา: D = VT; ต้องการเวลาให้ใช้ T = D÷V"},
  {"category":"เลขยกกำลัง","prompt":"ข้อใดเป็นค่าที่ถูกต้องของ 2^8 x 4^3 หารด้วย 8^2","answer":"2^8","choices":["2^6","2^8","2^10","2^12"],"explanation":"ทำให้ทุกจำนวนอยู่ในรูปเลขยกกำลังฐานเดียวกันก่อน โดย 4 = 2^2 ดังนั้น 4^3 = (2^2)^3 = 2^6 และ 8 = 2^3 ดังนั้น 8^2 = (2^3)^2 = 2^6 นิพจน์จึงกลายเป็น (2^8 × 2^6) ÷ 2^6 เมื่อคูณเลขฐานเดียวกันให้บวกเลขชี้กำลัง และเมื่อหารให้ลบเลขชี้กำลัง จึงได้ 2^(8+6-6) = 2^8 หรือมองว่า 2^6 ด้านบนและด้านล่างตัดกัน เหลือ 2^8 ดังนั้นคำตอบคือ 2^8","tip":"จำสั้น ๆ: เลขยกกำลังหลายฐาน ให้แปลงทุกจำนวนเป็นฐานเดียวกันก่อน แล้วค่อยใช้กฎคูณบวกชี้กำลัง/หารลบชี้กำลัง"},
  {"category":"ลำดับเลขคณิต","prompt":"ลำดับเลขคณิตมีพจน์แรก 7 และผลต่างร่วม 4 พจน์ที่ 20 มีค่าเท่าใด","answer":"83","choices":["79","81","83","87"],"explanation":"ลำดับเลขคณิตใช้สูตรพจน์ที่ n คือ a_n = a_1 + (n - 1)d โดยโจทย์ให้พจน์แรก a_1 = 7 ผลต่างร่วม d = 4 และต้องการพจน์ที่ 20 จึงแทนค่าเป็น a_20 = 7 + (20 - 1) × 4 = 7 + 19 × 4 = 7 + 76 = 83 เหตุผลที่ใช้ 19 ครั้ง ไม่ใช่ 20 ครั้ง เพราะจากพจน์ที่ 1 ไปถึงพจน์ที่ 20 มีช่วงเพิ่มทั้งหมด 19 ช่วง ดังนั้นพจน์ที่ 20 เท่ากับ 83","tip":"จำสั้น ๆ: พจน์ที่ n ของลำดับเลขคณิต = a₁ + (n−1)d; จำว่า “จากพจน์ 1 ไปพจน์ n มี n−1 ช่อง”"},
  {"category":"พีทาคอรัส","prompt":"สามเหลี่ยมมุมฉากมีด้านประกอบมุมฉากยาว 9 และ 12 หน่วย ด้านตรงข้ามมุมฉากยาวเท่าใด","answer":"15","choices":["13","14","15","16"],"explanation":"สามเหลี่ยมมุมฉากใช้ทฤษฎีพีทาคอรัส c^2 = a^2 + b^2 โดย c คือด้านตรงข้ามมุมฉากและเป็นด้านที่ยาวที่สุด เมื่อด้านประกอบมุมฉากยาว 9 และ 12 หน่วย จะได้ c^2 = 9^2 + 12^2 = 81 + 144 = 225 ดังนั้น c = √225 = 15 หน่วย นอกจากนี้ 9 : 12 : 15 เป็น 3 เท่าของชุดพีทาคอรัส 3 : 4 : 5 จึงสามารถใช้เป็นวิธีตรวจคำตอบได้ ดังนั้นด้านตรงข้ามมุมฉากยาว 15 หน่วย","tip":"จำสั้น ๆ: สามเหลี่ยมมุมฉากให้มองหาชุด 3-4-5 และพหุคูณก่อน ถ้าไม่เจอค่อยใช้ c² = a²+b²"},
  {"category":"พื้นที่วงกลม","prompt":"วงกลมรัศมี 7 ซม. มีพื้นที่เท่าใด กำหนด π = 22/7","answer":"154 ตารางซม.","choices":["77 ตารางซม.","154 ตารางซม.","308 ตารางซม.","44 ตารางซม."],"explanation":"พื้นที่วงกลมใช้สูตร A = πr^2 โดยรัศมี r = 7 ซม. และโจทย์กำหนด π = 22/7 แทนค่าได้ A = (22/7) × 7^2 = (22/7) × 7 × 7 ตัด 7 ที่ตัวส่วนกับ 7 หนึ่งตัวที่ตัวเศษ เหลือ 22 × 7 = 154 ดังนั้นพื้นที่เท่ากับ 154 ตารางเซนติเมตร ต้องระวังไม่สับสนกับสูตรเส้นรอบวง 2πr ซึ่งจะให้คำตอบคนละชนิดกัน","tip":"จำสั้น ๆ: “พื้นที่วงกลม” = πr² แต่ “เส้นรอบวง” = 2πr — ดูหน่วยตอบด้วย พื้นที่ต้องเป็นหน่วย²"},
  {"category":"ปริมาตร","prompt":"กล่องทรงสี่เหลี่ยมมุมฉากกว้าง 5 ซม. ยาว 8 ซม. สูง 6 ซม. มีปริมาตรเท่าใด","answer":"240 ลูกบาศก์ซม.","choices":["160 ลูกบาศก์ซม.","190 ลูกบาศก์ซม.","240 ลูกบาศก์ซม.","480 ลูกบาศก์ซม."],"explanation":"ปริมาตรของกล่องทรงสี่เหลี่ยมมุมฉากคำนวณจาก กว้าง × ยาว × สูง เมื่อกว้าง 5 ซม. ยาว 8 ซม. และสูง 6 ซม. จะได้ปริมาตร = 5 × 8 × 6 เริ่มจาก 5 × 8 = 40 แล้ว 40 × 6 = 240 ดังนั้นปริมาตรเท่ากับ 240 ลูกบาศก์เซนติเมตร หน่วยต้องเป็น ‘ลูกบาศก์เซนติเมตร’ เพราะเป็นการวัดปริมาตรสามมิติ ไม่ใช่ตารางเซนติเมตรซึ่งเป็นหน่วยพื้นที่","tip":"จำสั้น ๆ: ปริมาตรกล่อง = กว้าง×ยาว×สูง และคำตอบต้องเป็นหน่วย³ ไม่ใช่หน่วย²"},
  {"category":"สถิติ","prompt":"ข้อมูล 4, 7, 7, 8, 10, 12, 12, 12, 15 มีมัธยฐานเท่าใด","answer":"10","choices":["8","9","10","12"],"explanation":"ข้อมูลมีทั้งหมด 9 ค่าและเรียงจากน้อยไปมากอยู่แล้ว คือ 4, 7, 7, 8, 10, 12, 12, 12, 15 เมื่อจำนวนข้อมูลเป็นจำนวนคี่ มัธยฐานคือค่าที่อยู่ตรงกลางพอดี ตำแหน่งของค่ากลางหาได้จาก (n + 1) ÷ 2 = (9 + 1) ÷ 2 = 5 ดังนั้นดูค่าลำดับที่ 5 ซึ่งคือ 10 จึงได้มัธยฐานเท่ากับ 10 ถ้าข้อมูลยังไม่เรียงลำดับต้องเรียงก่อนเสมอ","tip":"จำสั้น ๆ: มัธยฐานต้อง “เรียงข้อมูลก่อน” เสมอ; ถ้ามี n ค่าเป็นจำนวนคี่ ตำแหน่งกลางคือ (n+1)÷2"},
  {"category":"ค่าเฉลี่ย","prompt":"ค่าเฉลี่ยของ 6, 8, 10, x, 16 เท่ากับ 12 ค่า x เท่ากับเท่าใด","answer":"20","choices":["18","20","22","24"],"explanation":"ค่าเฉลี่ย = ผลรวมของข้อมูล ÷ จำนวนข้อมูล ในโจทย์มีข้อมูล 5 ค่า คือ 6, 8, 10, x, 16 และมีค่าเฉลี่ย 12 ดังนั้นผลรวมของข้อมูลทั้งหมดต้องเท่ากับ 12 × 5 = 60 ผลรวมของค่าที่ทราบแล้วคือ 6 + 8 + 10 + 16 = 40 จึงได้ 40 + x = 60 ย้าย 40 ไปอีกข้างได้ x = 60 - 40 = 20 ตรวจสอบ: 6 + 8 + 10 + 20 + 16 = 60 และ 60 ÷ 5 = 12 ตรงตามโจทย์ ดังนั้น x = 20","tip":"จำสั้น ๆ: ค่าเฉลี่ย × จำนวนข้อมูล = ผลรวม ใช้สมการนี้ย้อนหาค่าที่หายไปได้เร็วที่สุด"},
  {"category":"เซต","prompt":"ในห้องมี 60 คน ชอบฟุตบอล 35 คน ชอบบาสเกตบอล 28 คน และชอบทั้งสองอย่าง 12 คน คนที่ชอบอย่างน้อยหนึ่งอย่างมีกี่คน","answer":"51 คน","choices":["47 คน","51 คน","60 คน","63 คน"],"explanation":"ต้องการหาจำนวนคนที่ชอบอย่างน้อยหนึ่งชนิด จึงใช้หลักบวกลบของเซต n(A ∪ B) = n(A) + n(B) - n(A ∩ B) เพราะคนที่ชอบทั้งฟุตบอลและบาสเกตบอลถูกนับซ้ำอยู่ใน 35 คนและ 28 คนแล้วหนึ่งครั้ง จึงต้องลบส่วนซ้ำออกหนึ่งครั้ง แทนค่าได้ 35 + 28 - 12 = 63 - 12 = 51 คน ดังนั้นมีคนที่ชอบอย่างน้อยหนึ่งอย่าง 51 คน ส่วนจำนวนคนที่ไม่ชอบทั้งสองอย่างคือ 60 - 51 = 9 คน ซึ่งใช้ตรวจสอบความสมเหตุสมผลได้","tip":"จำสั้น ๆ: สองเซตใช้ A∪B = A + B − ส่วนซ้ำ เพราะสมาชิกที่อยู่ทั้งสองกลุ่มถูกนับไปแล้ว 2 ครั้ง"},
  {"category":"เซต","prompt":"ถ้าเซต B มีสมาชิก 5 ตัว เซต B มีสับเซตทั้งหมดกี่สับเซต","answer":"32","choices":["10","16","25","32"],"explanation":"เซต B มีสมาชิก 5 ตัว ในการสร้างสับเซต สมาชิกแต่ละตัวมีทางเลือก 2 แบบ คือ “เลือกสมาชิกตัวนั้นเข้ามาในสับเซต” หรือ “ไม่เลือก” เมื่อมีสมาชิก 5 ตัว จำนวนทางเลือกทั้งหมดจึงเป็น 2 × 2 × 2 × 2 × 2 = 2^5 = 32 สับเซต จำนวนนี้รวมทั้งเซตว่าง ∅ และเซต B เองด้วย ดังนั้นเซต B มีสับเซตทั้งหมด 32 สับเซต","tip":"จำสั้น ๆ: เซตมีสมาชิก n ตัว → จำนวนสับเซตทั้งหมด = 2ⁿ เพราะสมาชิกแต่ละตัวมี 2 ทางเลือก: เลือกหรือไม่เลือก"},
  {"category":"ค.ร.น.","prompt":"สัญญาณไฟ 3 ดวงกระพริบทุก 12, 18 และ 30 วินาที ถ้ากระพริบพร้อมกันตอนนี้ จะพร้อมกันอีกครั้งในกี่วินาที","answer":"180 วินาที","choices":["90 วินาที","120 วินาที","150 วินาที","180 วินาที"],"explanation":"เหตุการณ์ที่จะเกิดพร้อมกันอีกครั้งต้องหาค.ร.น.ของรอบเวลา 12, 18 และ 30 วินาที แยกตัวประกอบได้ 12 = 2^2 × 3, 18 = 2 × 3^2 และ 30 = 2 × 3 × 5 การหาค.ร.น.เลือกตัวประกอบทุกชนิดโดยใช้เลขชี้กำลังที่มากที่สุด จึงได้ 2^2 × 3^2 × 5 = 4 × 9 × 5 = 180 ดังนั้นหลังจากกระพริบพร้อมกันตอนนี้ จะกระพริบพร้อมกันอีกครั้งใน 180 วินาที หรือ 3 นาที","tip":"จำสั้น ๆ: เหตุการณ์หลายอย่าง “เกิดพร้อมกันอีกครั้งเมื่อไร” ให้คิด ค.ร.น. ของรอบเวลา"},
  {"category":"ห.ร.ม.","prompt":"ห.ร.ม. ของ 84 และ 126 มีค่าเท่าใด","answer":"42","choices":["21","28","42","63"],"explanation":"แยกตัวประกอบเฉพาะของทั้งสองจำนวนก่อน: 84 = 2^2 × 3 × 7 และ 126 = 2 × 3^2 × 7 การหาห.ร.ม.ต้องเลือกเฉพาะตัวประกอบที่มีร่วมกันทั้งสองจำนวน และเลือกเลขชี้กำลังที่น้อยที่สุด จึงได้ 2^1 × 3^1 × 7^1 = 2 × 3 × 7 = 42 สามารถตรวจสอบได้ว่า 84 ÷ 42 = 2 และ 126 ÷ 42 = 3 ซึ่งเป็นจำนวนเต็มทั้งคู่ ดังนั้นห.ร.ม.เท่ากับ 42","tip":"จำสั้น ๆ: ห.ร.ม. = เลือกเฉพาะตัวประกอบที่ทุกจำนวนมีร่วมกัน และใช้เลขชี้กำลัง “น้อยที่สุด”"},
  {"category":"การหารเอาเศษ","prompt":"จำนวนเต็มบวกที่น้อยที่สุดซึ่งเมื่อหารด้วย 5 เหลือเศษ 2 และหารด้วย 3 เหลือเศษ 1 คือจำนวนใด","answer":"7","choices":["4","7","12","17"],"explanation":"ต้องหาจำนวนเต็มบวกที่น้อยที่สุดที่ตรงสองเงื่อนไขพร้อมกัน เริ่มจากเงื่อนไขหารด้วย 5 แล้วเหลือเศษ 2 จำนวนที่เป็นไปได้เรียงจากน้อยคือ 2, 7, 12, 17, ... จากนั้นตรวจทีละจำนวนกับเงื่อนไขที่สองว่าหารด้วย 3 ต้องเหลือเศษ 1 โดย 2 ÷ 3 เหลือเศษ 2 จึงยังไม่ใช่ ส่วน 7 ÷ 3 = 2 เศษ 1 จึงตรงเงื่อนไขทั้งสองและเป็นจำนวนที่พบเป็นตัวแรก ดังนั้นจำนวนเต็มบวกที่น้อยที่สุดคือ 7","tip":"จำสั้น ๆ: โจทย์เศษจำนวนน้อย ให้ไล่ค่าจากเงื่อนไขหนึ่งก่อน แล้วตรวจอีกเงื่อนไข จะเร็วกว่าแก้สมการเต็มรูป"},
  {"category":"ตรรกศาสตร์","prompt":"ถ้า p เป็นจริง และ q เป็นเท็จ ค่าความจริงของ ~(p ∧ q) เป็นอย่างไร","answer":"จริง","choices":["จริง","เท็จ","สรุปไม่ได้","เป็นได้ทั้งจริงและเท็จ"],"explanation":"กำหนดให้ p เป็นจริง และ q เป็นเท็จ ขั้นแรกพิจารณาค่าภายในวงเล็บ p ∧ q เครื่องหมาย ∧ หมายถึง ‘และ’ ซึ่งจะเป็นจริงก็ต่อเมื่อทั้ง p และ q เป็นจริงพร้อมกันเท่านั้น แต่ในที่นี้ q เป็นเท็จ ดังนั้น p ∧ q = จริง ∧ เท็จ = เท็จ จากนั้นมีเครื่องหมาย ~ อยู่หน้าวงเล็บซึ่งหมายถึงการนิเสธ จึงกลับค่าจากเท็จเป็นจริง ดังนั้น ~(p ∧ q) มีค่าความจริงเป็น ‘จริง’","tip":"จำสั้น ๆ: ตรรกศาสตร์ให้ทำ “วงเล็บก่อน นิเสธทีหลัง”; p∧q จะจริงก็ต่อเมื่อทั้งสองเป็นจริงเท่านั้น"},
  {"category":"สัญลักษณ์แทนการคำนวณ","prompt":"กำหนดให้ a ★ b = 2a + b และ a ● b = a - 2b แล้ว (5 ★ 3) ● 4 มีค่าเท่าใด","answer":"5","choices":["3","5","9","13"],"explanation":"โจทย์กำหนดความหมายของสัญลักษณ์ใหม่ จึงต้องคำนวณตามนิยามที่ให้มา ไม่ใช้ความหมายตามปกติ เริ่มจากวงเล็บด้านใน (5 ★ 3) โดย a ★ b = 2a + b แทน a = 5 และ b = 3 ได้ 5 ★ 3 = 2(5) + 3 = 10 + 3 = 13 จากนั้นนำผลลัพธ์ 13 ไปคำนวณ 13 ● 4 โดย a ● b = a - 2b จึงได้ 13 ● 4 = 13 - 2(4) = 13 - 8 = 5 ดังนั้นค่าของ (5 ★ 3) ● 4 เท่ากับ 5","tip":"จำสั้น ๆ: สัญลักษณ์พิเศษไม่มีความหมายตายตัว ให้อ่านนิยามที่โจทย์ให้ แล้วคำนวณจากวงเล็บด้านในออกมาทีละชั้น"}
]
$questions$::jsonb) with ordinality;

insert into public.questions (id, category, prompt, choices, metadata)
select
  'police-math-set-04-q' || lpad(position::text, 2, '0'),
  data->>'category',
  data->>'prompt',
  data->'choices',
  jsonb_build_object(
    'source_exam_set', 'general-exam-set-4',
    'explanation_version', 'premium-csv-2026-08-23'
  )
from seed_police_math_set_04
on conflict (id) do update set
  category = excluded.category,
  prompt = excluded.prompt,
  choices = excluded.choices,
  metadata = excluded.metadata;

insert into public.question_solutions (
  question_id, correct_choice_index, explanation, tip, metadata
)
select
  'police-math-set-04-q' || lpad(seed.position::text, 2, '0'),
  answer_choice.ordinality::integer - 1,
  seed.data->>'explanation',
  seed.data->>'tip',
  jsonb_build_object(
    'version', 2,
    'source', 'Supabase_SlothMove_Police_Math_Set04_Premium.csv'
  )
from seed_police_math_set_04 seed
cross join lateral (
  select choice.ordinality
  from jsonb_array_elements_text(seed.data->'choices') with ordinality as choice(value, ordinality)
  where choice.value = seed.data->>'answer'
) answer_choice
on conflict (question_id) do update set
  correct_choice_index = excluded.correct_choice_index,
  explanation = excluded.explanation,
  tip = excluded.tip,
  metadata = excluded.metadata;

insert into public.exam_set_questions (exam_set_id, question_id, position)
select
  'police-math-set-04',
  'police-math-set-04-q' || lpad(position::text, 2, '0'),
  position
from seed_police_math_set_04
on conflict (exam_set_id, question_id) do update set
  position = excluded.position;

do $$
declare
  seeded_count integer;
  solution_count integer;
begin
  select count(*) into seeded_count
  from public.exam_set_questions
  where exam_set_id = 'police-math-set-04';

  select count(*) into solution_count
  from public.exam_set_questions mapping
  join public.question_solutions solution on solution.question_id = mapping.question_id
  where mapping.exam_set_id = 'police-math-set-04';

  if seeded_count <> 30 or solution_count <> 30 then
    raise exception 'Seed validation failed: questions %, solutions %', seeded_count, solution_count;
  end if;
end $$;

commit;
